import AVFoundation
import Foundation

/// Plays everything the app says or sounds like. It needs no audio files to work:
/// effects are generated by code and animals are spoken by the built-in voice.
/// Add a file with a matching name (see GUIDE.md) and it is used automatically.
@MainActor
final class Sound {
    static let shared = Sound()

    enum Effect: String, CaseIterable {
        case pop, boing, giggle, chime, fanfare
    }

    var isEnabled = true {
        didSet {
            if !isEnabled { stopAll() }
        }
    }

    private let speech = AVSpeechSynthesizer()
    private var clips: [Effect: Data] = [:]
    private var purrClip = Data()
    private var players: [AVAudioPlayer] = []
    private var callPlayer: AVAudioPlayer?
    private var purrPlayer: AVAudioPlayer?
    private var nameTask: Task<Void, Never>?
    private var lastPop = Date.distantPast

    private init() {
        // .playback means sounds still play when the ringer switch is on silent.
        // The parent menu's sound toggle is what mutes the app.
        try? AVAudioSession.sharedInstance().setCategory(.playback)
        try? AVAudioSession.sharedInstance().setActive(true)

        for effect in Effect.allCases {
            clips[effect] = ToneSynth.clip(for: effect)
        }
        purrClip = ToneSynth.purr()
    }

    // MARK: Effects

    func play(_ effect: Effect, volume: Float = 1) {
        guard isEnabled else { return }
        let player = filePlayer(named: "fx_\(effect.rawValue)") ?? clipPlayer(for: effect)
        guard let player else { return }
        players.removeAll { !$0.isPlaying }
        player.volume = volume
        player.play()
        players.append(player)
    }

    /// The soft pop on every touch, limited so that mashing the screen stays pleasant.
    func pop() {
        guard Date().timeIntervalSince(lastPop) > 0.12 else { return }
        lastPop = Date()
        play(.pop, volume: 0.4)
    }

    func startPurr() {
        guard isEnabled, purrPlayer == nil else { return }
        let player = filePlayer(named: "fx_purr") ?? (try? AVAudioPlayer(data: purrClip))
        player?.numberOfLoops = -1
        player?.play()
        purrPlayer = player
    }

    func stopPurr() {
        purrPlayer?.stop()
        purrPlayer = nil
    }

    // MARK: Animals

    /// Plays the animal's call and returns roughly how long it lasts.
    @discardableResult
    func animalCall(_ animal: Animal) -> Double {
        guard isEnabled else { return 0 }
        interruptVoices()
        if let player = filePlayer(named: "sound_\(animal.id)") {
            player.play()
            callPlayer = player
            return player.duration
        }
        speak(animal.call, pitch: animal.pitch)
        return 0.9
    }

    /// Plays the animal's call, then a voice says its name.
    func animalCallThenName(_ animal: Animal) {
        guard isEnabled else { return }
        let wait = min(animalCall(animal), 2.5) + 0.1
        nameTask = Task {
            try? await Task.sleep(for: .seconds(wait))
            guard !Task.isCancelled else { return }
            self.sayName(animal)
        }
    }

    private func sayName(_ animal: Animal) {
        if let player = filePlayer(named: "name_\(animal.id)") {
            player.play()
            callPlayer = player
        } else {
            speak(animal.name, pitch: 1.2)
        }
    }

    // MARK: Voice

    func say(_ text: String) {
        guard isEnabled else { return }
        interruptVoices()
        speak(text, pitch: 1.3)
    }

    /// The slow, low voice for the "all done" screen.
    func sayAllDone() {
        guard isEnabled else { return }
        interruptVoices()
        if let player = filePlayer(named: "say_alldone") {
            player.play()
            callPlayer = player
        } else {
            speak(Words.allDone, pitch: 0.85, rate: 0.34)
        }
    }

    func stopAll() {
        interruptVoices()
        stopPurr()
        for player in players {
            player.stop()
        }
        players.removeAll()
    }

    // MARK: Helpers

    private func interruptVoices() {
        nameTask?.cancel()
        nameTask = nil
        callPlayer?.stop()
        callPlayer = nil
        speech.stopSpeaking(at: .immediate)
    }

    private func speak(_ text: String, pitch: Float, rate: Float = 0.42) {
        let utterance = AVSpeechUtterance(string: text)
        utterance.pitchMultiplier = pitch
        utterance.rate = rate
        utterance.voice = AVSpeechSynthesisVoice(language: Words.voiceLanguage)
        speech.speak(utterance)
    }

    private func clipPlayer(for effect: Effect) -> AVAudioPlayer? {
        guard let data = clips[effect] else { return nil }
        return try? AVAudioPlayer(data: data)
    }

    /// Finds an audio file you added to the project, if there is one.
    private func filePlayer(named name: String) -> AVAudioPlayer? {
        for fileExtension in ["m4a", "mp3", "wav", "caf"] {
            if let url = Bundle.main.url(forResource: name, withExtension: fileExtension),
               let player = try? AVAudioPlayer(contentsOf: url) {
                return player
            }
        }
        return nil
    }
}

/// Builds little WAV sounds in memory.
enum ToneSynth {
    private static let sampleRate = 22050.0

    private struct Note {
        let startHz: Double
        let endHz: Double
        let seconds: Double
        var gain: Double = 0.8
    }

    static func clip(for effect: Sound.Effect) -> Data {
        switch effect {
        case .pop:
            return wav(notes: [Note(startHz: 500, endHz: 950, seconds: 0.09)])
        case .boing:
            return wav(notes: [Note(startHz: 260, endHz: 620, seconds: 0.2)])
        case .giggle:
            let chirps = [700.0, 820.0, 760.0, 900.0, 840.0, 1000.0]
            return wav(notes: chirps.map { Note(startHz: $0, endHz: $0 * 1.35, seconds: 0.09) })
        case .chime:
            return wav(notes: [
                Note(startHz: 880, endHz: 880, seconds: 0.14),
                Note(startHz: 1175, endHz: 1175, seconds: 0.28)
            ])
        case .fanfare:
            let steps = [523.0, 659.0, 784.0, 1047.0]
            return wav(notes: steps.map { Note(startHz: $0, endHz: $0, seconds: 0.17) })
        }
    }

    private static func wav(notes: [Note]) -> Data {
        var samples: [Int16] = []
        for note in notes {
            let count = Int(note.seconds * sampleRate)
            var phase = 0.0
            for index in 0..<count {
                let progress = Double(index) / Double(count)
                let hz = note.startHz + (note.endHz - note.startHz) * progress
                phase += 2.0 * Double.pi * hz / sampleRate
                let attack = min(1.0, progress * 20.0)
                let decay = pow(1.0 - progress, 1.5)
                let tone = (sin(phase) + 0.3 * sin(2.0 * phase)) / 1.3
                samples.append(toSample(tone * attack * decay * note.gain))
            }
        }
        return wrapInWAV(samples)
    }

    /// Two seconds of soft rumbling noise that loops cleanly.
    static func purr() -> Data {
        let count = Int(2.0 * sampleRate)
        var samples: [Int16] = []
        samples.reserveCapacity(count)
        var filtered = 0.0
        for index in 0..<count {
            let seconds = Double(index) / sampleRate
            filtered += 0.18 * (Double.random(in: -1...1) - filtered)
            let flutter = 0.5 + 0.5 * sin(2.0 * Double.pi * 24.0 * seconds)
            samples.append(toSample(filtered * flutter * flutter * 2.2))
        }
        return wrapInWAV(samples)
    }

    private static func toSample(_ value: Double) -> Int16 {
        Int16(max(-1.0, min(1.0, value)) * 32000.0)
    }

    private static func wrapInWAV(_ samples: [Int16]) -> Data {
        let rate = UInt32(sampleRate)
        let dataSize = UInt32(samples.count * 2)
        var data = Data()

        func add(_ text: String) {
            data.append(contentsOf: Array(text.utf8))
        }
        func add32(_ value: UInt32) {
            withUnsafeBytes(of: value.littleEndian) { data.append(contentsOf: $0) }
        }
        func add16(_ value: UInt16) {
            withUnsafeBytes(of: value.littleEndian) { data.append(contentsOf: $0) }
        }

        add("RIFF")
        add32(36 + dataSize)
        add("WAVE")
        add("fmt ")
        add32(16)
        add16(1)          // uncompressed
        add16(1)          // mono
        add32(rate)
        add32(rate * 2)   // bytes per second
        add16(2)          // bytes per sample
        add16(16)         // bits per sample
        add("data")
        add32(dataSize)
        for sample in samples {
            add16(UInt16(bitPattern: sample))
        }
        return data
    }
}
